import type { LabCode } from './codes.ts';

// A teammate's Lab type. It compiles — and lets wrong labs in.
export type Lab = {
  code: string;
  name: string;
  capacity?: number;
  equipment: string[];
};

export function freeSeats(lab: Lab, booked: number): number {
  return Math.max(0, (lab.capacity ?? 0) - booked);
}

// LabFlow lab codes (given — do not edit).
export const LABS = ['BE-201', 'BE-202', 'AL-301'] as const;
export type LabCode = (typeof LABS)[number];

import type { Lab } from '../src/lab.ts';

const be201: Lab = { code: 'BE-201', name: 'Backend Lab 1', capacity: 40, equipment: ['projector'] };
const be202: Lab = { code: 'BE-202', name: 'Backend Lab 2', capacity: 40 }; // not recorded yet
const count: number = be201.equipment?.length ?? 0;
export { be201, be202, count };

import type { Lab } from '../src/lab.ts';

declare const lab: Lab;
const ai: Lab = { code: 'AL-301', name: 'AI Lab' }; // expect TS2741
const ghost: Lab = { code: 'BE-999', name: 'Ghost', capacity: 10 }; // expect TS2322
const typo: Lab = { code: 'BE-201', name: 'Backend Lab 1', capasity: 40 }; // expect TS2561
lab.code = 'BE-202'; // expect TS2540
const n: number = lab.equipment.length; // expect TS18048
export { ai, ghost, typo, n };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { freeSeats } from '../src/lab.ts';

test('free seats', () => assert.equal(freeSeats({ code: 'BE-201', name: 'Backend Lab 1', capacity: 40 }, 12), 28));
test('never below 0', () => assert.equal(freeSeats({ code: 'AL-301', name: 'AI Lab', capacity: 30 }, 35), 0));

