import type { Lab } from './types.ts';

// Seed data, built first and collected at the end.
const be201 = { code: 'BE-201', name: 'Backend Lab 1', capacity: 40 } as const;
const be202 = { code: 'BE-202', name: 'Backend Lab 2', capacity: 40 } as const;
const al301 = { code: 'AL-301', name: 'AI Lab', capasity: 30 } as const;

export const SEED: Lab[] = [be201, be202, al301];

// LabFlow lab codes (given — do not edit).
export const LABS = ['BE-201', 'BE-202', 'AL-301'] as const;
export type LabCode = (typeof LABS)[number];

import type { LabCode } from './codes.ts';

// The data model (given — do not edit). capacity is required on purpose.
export type Lab = { readonly code: LabCode; name: string; capacity: number };

export function freeSeats(lab: Lab, booked: number): number {
  return Math.max(0, lab.capacity - booked);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { SEED } from '../src/seed.ts';
import { freeSeats } from '../src/types.ts';

test('three labs', () => assert.deepEqual(SEED.map((l) => l.code), ['BE-201', 'BE-202', 'AL-301']));
test('the AI lab has 30 seats', () => {
  const ai = SEED[2];
  assert.ok(ai);
  assert.equal(freeSeats(ai, 10), 20);
});
test('every capacity is a number', () => assert.ok(SEED.every((l) => typeof l.capacity === 'number')));

