import type { LabCode } from './codes.ts';

export type Lab = {
  code: LabCode;
  name: string;
  capacity: number;
  equipment: string[];
};

export const STANDARD: string[] = ['projector', 'whiteboard'];

// Adds one item to a lab's equipment.
export function addEquipment(lab: Lab, item: string): Lab {
  lab.equipment.push(item);
  return lab;
}

// LabFlow lab codes (given — do not edit).
export const LABS = ['BE-201', 'BE-202', 'AL-301'] as const;
export type LabCode = (typeof LABS)[number];

import { STANDARD } from '../src/lab.ts';
import type { Lab } from '../src/lab.ts';

declare const lab: Lab;
lab.code = 'BE-202'; // expect TS2540
lab.equipment = []; // expect TS2540
lab.equipment.push('printer'); // expect TS2339
STANDARD.push('printer'); // expect TS2339

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { STANDARD, addEquipment } from '../src/lab.ts';
import type { Lab } from '../src/lab.ts';

const be201: Lab = { code: 'BE-201', name: 'Backend Lab 1', capacity: 40, equipment: STANDARD };
const be202: Lab = { code: 'BE-202', name: 'Backend Lab 2', capacity: 40, equipment: STANDARD };

test('the new lab has the item', () => assert.deepEqual(addEquipment(be201, 'GPU server').equipment, ['projector', 'whiteboard', 'GPU server']));
test('the other lab is untouched', () => {
  addEquipment(be201, 'GPU server');
  assert.deepEqual(be202.equipment, ['projector', 'whiteboard']);
});
test('the old lab is untouched', () => {
  addEquipment(be201, 'GPU server');
  assert.deepEqual(be201.equipment, ['projector', 'whiteboard']);
});

