import type { LabCode } from './codes.ts';

export type Lab = {
  readonly code: LabCode;
  name: string;
  capacity: number;
  readonly equipment: readonly string[]; // the property AND the list
};

export const STANDARD: readonly string[] = ['projector', 'whiteboard'];

